(function(){function s(e){e.forEach(t=>t.classList.add("is-visible"))}function o(){const e=document.querySelectorAll("[data-animate]");if(!e.length)return;const t=window.matchMedia("(prefers-reduced-motion: reduce)");if(!("IntersectionObserver"in window)||t.matches){s(e);return}const n=new IntersectionObserver(i=>{i.forEach(r=>{r.isIntersecting&&(r.target.classList.add("is-visible"),n.unobserve(r.target))})},{threshold:.2,rootMargin:"0px 0px -10% 0px"});e.forEach(i=>{n.observe(i)}),t.addEventListener("change",()=>{t.matches&&(s(e),n.disconnect())})}document.addEventListener("DOMContentLoaded",o)})();
